public class MarkupTagStripperTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("two tag pairs", "Hi there",
                MarkupTagStripper.stripTags("<b>Hi</b> <i>there</i>"));
        check("tag with attributes", "link",
                MarkupTagStripper.stripTags("<a href=\"x\">link</a>"));
        check("no tags at all", "plain", MarkupTagStripper.stripTags("plain"));
        check("empty input", "", MarkupTagStripper.stripTags(""));
        check("nested tags", "bold and italic",
                MarkupTagStripper.stripTags("<p><b>bold</b> and <i>italic</i></p>"));
        check("two doubles", "the cat sat down",
                MarkupTagStripper.collapseDoubles("the the cat sat sat down"));
        check("nothing to collapse", "a b c",
                MarkupTagStripper.collapseDoubles("a b c"));
        check("triple collapses once", "hi hi",
                MarkupTagStripper.collapseDoubles("hi hi hi"));
        check("different words untouched", "red green",
                MarkupTagStripper.collapseDoubles("red green"));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

