public class MarkupTagStripper {

    public static String stripTags(String html) {
        if (html == null) {
            return "";
        }
        return html.replaceAll("<.*?>", "");
    }

    public static String collapseDoubles(String text) {
        if (text == null) {
            return "";
        }
        return text.replaceAll("\\b(\\w+) \\1\\b", "$1");
    }
}
